import{_ as t,o as e,c as s,a5 as d}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Offline & synchronisation","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/10-offline-sync.md","filePath":"generated/modules/10-offline-sync.md","lastUpdated":null}'),n={name:"modules/10-offline-sync.md"};function r(o,a,p,i,l,c){return e(),s("div",null,[...a[0]||(a[0]=[d('<h1 id="offline-synchronisation" tabindex="-1">Offline &amp; synchronisation <a class="header-anchor" href="#offline-synchronisation" aria-label="Permalink to &quot;Offline &amp; synchronisation&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 0-1 · <a href="/VendoraSystem-docs/specs/10-offline-sync">spécification complète</a></span></p><p>Protocole maison : outbox transactionnelle sur chaque appareil, journal append-only autoritaire sur le serveur, push idempotent et pull par curseur, projections partagées, plus un hub local temps réel sur le Wi-Fi du magasin. Le cœur est livré et prouvé depuis les phases 0 et 1 ; le hub (lot 2.6) est sécurisé par clé LAN (2.26) et identité Ed25519 par appareil (2.28), la version minimale d&#39;app est en place (2.27). Restent la signature des lots push, la dead-letter, le bootstrap par snapshot, les avertissements d&#39;horloge et la validation du hub sur appareils physiques.</p><div class="kpis"><div><b>23</b><span>faites</span></div><div><b>9</b><span>partielles</span></div><div><b>2</b><span>à faire</span></div><div><b>1</b><span>bloquées</span></div></div><h2 id="journal-outbox" tabindex="-1">Journal &amp; outbox <a class="header-anchor" href="#journal-outbox" aria-label="Permalink to &quot;Journal &amp; outbox&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Outbox transactionnelle sur l&#39;appareil</strong><br><span class="muted">Chaque écriture métier (vente, session, mouvement…) et son événement sont enregistrés dans la même transaction SQLite ; numérotation sans trou qui survit au crash.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-01, RG-SYNC-02</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-ios">📷</a></td></tr><tr><td><strong>Journal d&#39;événements append-only côté serveur</strong><br><span class="muted"><code>event_log</code> refuse UPDATE et DELETE au niveau SQL, isolé par tenant (RLS FORCE), unique par (appareil, localSeq), <code>effective_at</code> calculé.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-02, RG-SYNC-05, RG-SYNC-08</td><td>0.x</td><td></td></tr></tbody></table><h2 id="push-pull" tabindex="-1">Push / pull <a class="header-anchor" href="#push-pull" aria-label="Permalink to &quot;Push / pull&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Push idempotent par eventId</strong><br><span class="muted">L&#39;appareil pousse son outbox par lots dans l&#39;ordre localSeq ; un événement déjà connu est confirmé sans doublon, y compris en push concurrent ; l&#39;outbox est repoussée après chaque synchro réussie.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-03, RG-SYNC-09</td><td>0.x, 1.x, 2.3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-android">📷</a></td></tr><tr><td><strong>Détection des trous de localSeq</strong><br><span class="muted">Un lot avec un trou de séquence est refusé (409, <code>gapDetected</code>, rien d&#39;inséré) et l&#39;appareil reprend depuis la séquence attendue.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-04</td><td>0.x, 1.x</td><td></td></tr><tr><td><strong>Pull incrémental par curseur serverSeq</strong><br><span class="muted">L&#39;appareil tire les événements des autres appareils dans l&#39;ordre serverSeq, en boucle, avec dédup et curseur persisté après application ; pull périodique de 20 s (10 s sur le KDS).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-05, RG-SYNC-11</td><td>0.x, 1.x, 2.5</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-android">📷</a></td></tr><tr><td><strong>Même code de projection partout</strong><br><span class="muted">Les événements reçus sont appliqués par les projecteurs du module partagé, que le serveur rejoue aussi (moteur fiscal, relais d&#39;additions, KDS).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-12</td><td>1.x, 2.2, 2.5</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-addition-table">📷</a></td></tr><tr><td><strong>Ré-appairage sous une nouvelle identité</strong><br><span class="muted">Un appareil désappairé puis réappairé purge ses événements confirmés et ré-estampille ses événements en attente, renumérotés depuis 1, pour repousser sans blocage.<br><i>Prouvé sur émulateur et simulateur ; à revérifier sur un vrai appareil lors des validations matérielles (TODO-PHASE1 §5).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-04, RG-SYNC-20</td><td>2.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-operations-addition">📷</a></td></tr></tbody></table><h2 id="rattrapage-projections" tabindex="-1">Rattrapage &amp; projections <a class="header-anchor" href="#rattrapage-projections" aria-label="Permalink to &quot;Rattrapage &amp; projections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Rattrapage ciblé <code>pending_backfill</code></strong><br><span class="muted">Une migration qui ajoute un projecteur sur un type d&#39;événement déjà reçu le marque à rejouer : la nouvelle projection se remplit depuis les événements déjà appliqués ; les documents de configuration sont stockés tels que reçus.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-24</td><td>2.1, 2.3, 2.15, 2.22, 2.23, 2.24, 2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-plan-de-salle">📷</a></td></tr><tr><td><strong>Rattrapage des projections serveur au démarrage</strong><br><span class="muted">Au démarrage, le serveur rejoue dans l&#39;ordre serverSeq les événements jamais projetés (additions, pourboires, rapprochement fournisseur), avec une clé d&#39;idempotence par projection.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-12</td><td>1.x, 2.13, 2.14</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-rattrapage-additions">📷</a></td></tr><tr><td><strong>Dead-letter des événements rejetés</strong><br><span class="muted">Un événement rejeté définitivement part dans une dead-letter locale et serveur, visible du manager, jamais repoussé ni supprimé en silence.<br><i>Lot R6 : statut par événement (<code>rejected</code>, <code>quarantined</code>), <code>event_dead_letter</code> serveur, chaîne <code>localSeq</code> préservée ; côté caisse statut REJECTED hors du push, badge ⚠ et liste. Lot R7 suite : un lot entier refusé (clé non reconnue, caisse révoquée) est gardé et dit en clair dans le bandeau avec la marche à suivre, effacé au premier envoi accepté ou au réappairage.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SYNC-10</td><td>R6, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r6-synchro">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-suite-canaux-rapports">📷</a></td></tr></tbody></table><h2 id="resolution-horloges" tabindex="-1">Résolution &amp; horloges <a class="header-anchor" href="#resolution-horloges" aria-label="Permalink to &quot;Résolution &amp; horloges&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Horloges décalées</strong><br><span class="muted">Heure serveur et heure de l&#39;appareil conservées, horodatage effectif borné, avertissement « heure de l&#39;appareil incorrecte » au-delà de 5 min.<br><i><code>effective_at</code> en colonne générée (phase 0) ; calcul du décalage d&#39;horloge, bandeau d&#39;avertissement et marquage <code>clockSuspect</code> non faits.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-06, RG-SYNC-07, RG-SYNC-08</td><td>0.x</td><td></td></tr><tr><td><strong>Catalogue en last-write-wins</strong><br><span class="muted">Le pull du catalogue et des documents de configuration applique la dernière version reçue ; le back-office refuse une version périmée (409).<br><i>LWW par version d&#39;entité, pas par champ ; trace <code>SyncConflictResolved</code> d&#39;une écriture écrasée non faite.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SYNC-15</td><td>0.x, 1.x</td><td></td></tr><tr><td><strong>Stock recalculé par somme des mouvements</strong><br><span class="muted">Deux caisses hors ligne vendant le même produit produisent deux mouvements ; le stock serveur et local est leur somme, négatif autorisé.<br><i>Projection stock avec anomalies journalisées (V5) ; l&#39;événement <code>StockAnomalyDetected</code> / alerte gérant de stock négatif n&#39;est pas émis.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SYNC-14</td><td>0.x, 1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-stock-web">📷</a></td></tr><tr><td><strong>Sessions de caisse propres à l&#39;appareil</strong><br><span class="muted">Seul l&#39;appareil ouvreur émet les événements de sa session ; clôture forcée hors ligne par un manager sur l&#39;appareil.<br><i>Clôture forcée offline faite ; le rejet serveur <code>SESSION_OWNERSHIP</code> n&#39;est pas implémenté ; les ventes de salle se rattachent à la session de la caisse principale par <code>sessionDeviceId</code> (RG-CASH-24).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-16</td><td>1.x, 2.15</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-login-pin-android">📷</a></td></tr><tr><td><strong>Fusion des fiches clients</strong><br><span class="muted">Fusion automatique sur téléphone E.164 identique, doublon probable soumis au manager, alias du perdant.<br><i>Fusion automatique par téléphone identique (lot 3.1) ; lot R7 : doublons probables et fusion manuelle validée par un manager (<code>CustomerMerged</code> MANUAL), appliquée par les caisses comme l&#39;automatique.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-SYNC-17</td><td>R7</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r7-clients-rapports">📷</a></td></tr></tbody></table><h2 id="hub-local" tabindex="-1">Hub local <a class="header-anchor" href="#hub-local" aria-label="Permalink to &quot;Hub local&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Découverte mDNS / NSD / Bonjour</strong><br><span class="muted">Chaque appareil annonce et résout <code>_possync._tcp</code> (NSD sur Android, Bonjour sur iOS avec permission réseau local), hub imposable « hôte:port ».<br><i>Prouvé entre émulateur et simulateur (l&#39;émulateur voit les annonces du Mac) ; permissions et isolation AP / IGMP à valider sur Wi-Fi magasin réel (VALIDATION-MATERIEL §7).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-19</td><td>0.x, 2.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-hub-local">📷</a></td></tr><tr><td><strong>Élection déterministe et ré-élection</strong><br><span class="muted">Caisse principale &gt; caisse &gt; KDS &gt; autres, puis uptime et deviceId ; heartbeat 5 s, silence 15 s → ré-élection.<br><i>Ré-élection &lt; 1 s au POC et 2 s après mise en arrière-plan de l&#39;iPhone (lot 2.26) ; chute brutale (kill, Wi-Fi coupé) à rejouer sur appareils physiques.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-19</td><td>0.x, 2.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-hub-local">📷</a></td></tr><tr><td><strong>Relais TCP temps réel</strong><br><span class="muted">Le hub rediffuse chaque événement local sans écho, avec dédup par eventId, une enveloppe JSON par ligne, même code sur les trois plateformes.<br><i>Relais en TCP au lieu de WebSocket, écart acté dans la spec 10 §4.4 (lot 2.26).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-18</td><td>0.x, 2.6, 2.26</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-hub-local">📷</a></td></tr><tr><td><strong>Rattrapage à la connexion au hub</strong><br><span class="muted">Un appareil qui rejoint le hub reçoit les événements manqués (journal borné 24 h / 5 000) et rejoue son outbox en attente.<br><i>Au-delà de 24 h / 5 000 événements, l&#39;appareil attend le pull cloud.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-19, RG-REST-16</td><td>2.6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-hub-local">📷</a></td></tr><tr><td><strong>Filtrage par rôle</strong><br><span class="muted">Le KDS ne reçoit que les événements de cuisine, le kiosque le catalogue et sa configuration, les autres rôles tout ; le rattrapage suit le même filtre.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-18</td><td>2.26</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-restaurant">📷</a></td></tr><tr><td><strong>Arrière-plan iOS</strong><br><span class="muted">L&#39;app iOS quitte proprement le réseau magasin en arrière-plan (ré-élection immédiate ailleurs) et le rejoint au premier plan avec rattrapage.<br><i>Choix assumé : pas de maintien du hub en arrière-plan sur iOS ; ré-élection côté Android 2 s après sur simulateur, à valider sur iPhone physique.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-19</td><td>2.26</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-restaurant">📷</a></td></tr><tr><td><strong>Sérialiseur LAN éphémère</strong><br><span class="muted">Le hub ordonne le temps réel local : départage d&#39;une même table ouverte deux fois, numéros de retrait séquentiels.<br><i>La même table est convergée par une règle déterministe sur chaque appareil (lot 2.12) plutôt que par le hub ; allocation des numéros séquentiels kiosque et désignation par le hub restent ouvertes.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-25</td><td>2.6, 2.12</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-convergence-table">📷</a></td></tr><tr><td><strong>Validation du hub sur 3 appareils physiques</strong><br><span class="muted">2 Android + 1 iPhone sur le Wi-Fi du magasin, internet coupé : permissions, élection, relais &lt; 2 s, chute brutale, arrière-plan, révocation et rotation de clé.<br><i>À exécuter par l&#39;utilisateur sur son matériel (VALIDATION-MATERIEL §7, TODO-PHASE1 §1) ; l&#39;émulateur Android (NAT) ne peut pas être hub d&#39;un iPhone.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-19, RG-SYNC-20, RG-REST-16</td><td>0.x, 2.6, 2.26, 2.28</td><td></td></tr></tbody></table><h2 id="securite-lan" tabindex="-1">Sécurité LAN <a class="header-anchor" href="#securite-lan" aria-label="Permalink to &quot;Sécurité LAN&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Clé LAN du magasin</strong><br><span class="muted">Le Hello et chaque enveloppe sont signés en HMAC-SHA256 d&#39;une clé de magasin servie par le serveur et tournée par l&#39;owner ; pair sans clé ou enveloppe forgée refusés et comptés.<br><i>Rotation sans coupure (lot R6) : grâce de 0 à 7 jours où l&#39;ancienne clé signe encore et les deux sont acceptées ; bouton au back-office. Refus d&#39;une mauvaise clé à rejouer sur appareils physiques (VALIDATION-MATERIEL).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SYNC-20</td><td>2.26, R6</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-restaurant">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r6-synchro">📷</a></td></tr><tr><td><strong>Identité Ed25519 par appareil</strong><br><span class="muted">Chaque appareil génère sa paire Ed25519 (Keystore / Keychain), enregistre sa clé publique une fois et signe son Hello et ses enveloppes, relayées telles quelles par le hub (protocole v3).<br><i>Prouvé entre émulateur et simulateur (vecteurs RFC 8032 sur les trois implémentations) ; à rejouer sur 3 appareils physiques (VALIDATION-MATERIEL §7).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-20</td><td>2.28</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-identite-appareil">📷</a></td></tr><tr><td><strong>Refus LAN des appareils révoqués ou inconnus</strong><br><span class="muted">L&#39;annuaire des pairs (statut ACTIVE / REVOKED, clé publique) est relu après chaque pull ; le hub refuse au Hello un appareil révoqué, inconnu du magasin ou à signature fausse, sans passer par le serveur.<br><i>Appareil jetable révoqué listé REVOKED dans l&#39;annuaire de l&#39;iPhone sur simulateur ; refus sur le LAN à valider sur appareils physiques.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-20</td><td>2.28</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-identite-appareil">📷</a></td></tr><tr><td><strong>Signature Ed25519 des lots push</strong><br><span class="muted">Chaque lot poussé au cloud est signé par l&#39;appareil et vérifié par le serveur, signature conservée dans <code>event_log</code> (non-répudiation).<br><i>Lot R6 : <code>PushSigning</code> (forme canonique du lot), signé par la clé Ed25519 de l&#39;appareil, vérifié par le serveur dès que la clé est enregistrée (403 BAD_SIGNATURE), signature gardée dans <code>event_log</code>. Lot R7 : iOS relit sa clé du trousseau à chaque signature (un désappairage puis un appairage dans le même lancement enregistraient une clé remplacée ensuite : lots refusés) ; chaque lot refusé est journalisé côté serveur.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-20</td><td>2.28, R6, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r6-synchro">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-clients-rapports">📷</a></td></tr></tbody></table><h2 id="versions-migrations" tabindex="-1">Versions &amp; migrations <a class="header-anchor" href="#versions-migrations" aria-label="Permalink to &quot;Versions &amp; migrations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Version minimale d&#39;app</strong><br><span class="muted">Chaque appel d&#39;appareil porte <code>X-App-Version</code> ; une app trop ancienne ou muette reçoit 426 et affiche « Mise à jour requise », continue hors ligne avec son outbox conservée.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-27</td><td>2.27</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-dette-technique">📷</a></td></tr><tr><td><strong>Versions de schéma des événements</strong><br><span class="muted">Le serveur accepte N, N-1, N-2 et upcaste ; un appareil qui reçoit une version trop récente suspend sa projection sans application partielle.<br><i>Non planifié au TRACKING : l&#39;enveloppe porte <code>schemaVersion</code> mais ni upcast ni table <code>pending_remote_event</code> ; la version minimale d&#39;app (lot 2.27) couvre le risque en pratique.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-23</td><td></td><td></td></tr><tr><td><strong>Migrations SQLDelight forward-only</strong><br><span class="muted">Schéma local versionné (<code>1.sqm</code> → <code>31.sqm</code>), migrations exécutées au démarrage, vérifiées par <code>verifyMigrations</code> et par un test de migration réelle, payloads d&#39;outbox gardés bruts.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-24</td><td>1.x, 2.1, 2.28</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-migrations">📷</a></td></tr><tr><td><strong>Bases locales exclues des sauvegardes</strong><br><span class="muted">Base et clés liées à l&#39;appareil : sauvegarde Android refusée, attribut d&#39;exclusion iOS sur chaque fichier ; une restauration rend une app vide à réappairer.<br><i>Prouvé sur émulateur (<code>bmgr</code> « Backup is not allowed ») et simulateur ; restauration sur appareils physiques à faire (VALIDATION-MATERIEL §8).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-AUTH-22</td><td>1.x, 2.27</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-dette-technique">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-cache-chiffre-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-cache-chiffre-ios">📷</a></td></tr></tbody></table><h2 id="longues-deconnexions" tabindex="-1">Longues déconnexions <a class="header-anchor" href="#longues-deconnexions" aria-label="Permalink to &quot;Longues déconnexions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Rétention locale et seuils d&#39;alerte</strong><br><span class="muted">Purge des événements confirmés après 7 jours, jamais des non confirmés ; alertes à 10 000 / 7 jours puis 50 000 / 21 jours sans jamais bloquer la vente.<br><i>Non suivi au TRACKING ; le code partagé expose <code>purgeConfirmedBefore</code> mais aucune app ne la planifie, et les seuils d&#39;alerte n&#39;existent pas.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-21</td><td>1.x</td><td></td></tr><tr><td><strong>Bootstrap par snapshot</strong><br><span class="muted">Un nouvel appareil ou un curseur expiré (&gt; 90 jours, 410 CURSOR_EXPIRED) s&#39;initialise par snapshot compacté + delta en moins de 5 min.<br><i>Lot R6 : <code>GET /sync/bootstrap</code>, journal compacté (<code>SnapshotCompaction</code>) appliqué en une transaction par un appareil neuf — prouvé : 204 événements au lieu de 744. Reste : <code>410 CURSOR_EXPIRED</code> (le serveur ne purge pas son journal) et copie pour un appareil déjà initialisé.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-22</td><td>R6</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r6-synchro">📷</a></td></tr></tbody></table><h2 id="indicateurs" tabindex="-1">Indicateurs <a class="header-anchor" href="#indicateurs" aria-label="Permalink to &quot;Indicateurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Indicateur d&#39;état de synchronisation</strong><br><span class="muted">Chaque appareil montre le nombre d&#39;événements à synchroniser, « · temps réel magasin » quand le hub est joint, le hors-ligne et « Mise à jour requise ».<br><i>Pas les 5 états de la spec ni le badge ⚠ (horloge, seuils, dead-letter) ; le libellé « temps réel magasin » Android n&#39;est pas rafraîchi à la perte du hub.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-21, RG-SYNC-27</td><td>1.x, 2.6, 2.27</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-hub-local">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-dette-technique">📷</a></td></tr><tr><td><strong>Flux temps réel depuis le cloud</strong><br><span class="muted">Variante WebSocket <code>/sync/stream</code> du pull quand le cloud est joignable (mêmes enveloppes, même curseur).<br><i>Non planifié : le pull périodique (20 s, 10 s sur KDS) et le hub local tiennent le temps réel.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-11</td><td></td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Signature Ed25519 des lots push vérifiée par le serveur (<code>event_log.signature</code>, RG-SYNC-20).</li><li>Dead-letter des événements rejetés et statut REJECTED par événement.</li><li>Décalage d&#39;horloge, avertissement d&#39;heure incorrecte et <code>clockSuspect</code>.</li><li>LWW par champ du catalogue et trace <code>SyncConflictResolved</code> ; rejet serveur <code>SESSION_OWNERSHIP</code>.</li><li>Upcast des versions de schéma et suspension de projection (RG-SYNC-23).</li><li>Purge planifiée de l&#39;outbox confirmée et seuils d&#39;alerte ; bootstrap par snapshot et <code>410 CURSOR_EXPIRED</code> ; endpoint <code>/sync/status</code>.</li><li>Rotation de la clé LAN sans coupure ; rattrapage hub au-delà de 24 h / 5 000 événements.</li><li>Numéros séquentiels alloués par le hub (kiosque) ; fusion des clients (phase 3).</li><li>Tests du hub sensibles à la charge (délais de 1 s, échecs ponctuels dans la passe globale).</li><li>Validations sur appareils physiques : hub à 3 appareils, révocation sur le LAN, sauvegarde / restauration (VALIDATION-MATERIEL §7 et §8).</li></ul>',24)])])}const g=t(n,[["render",r]]);export{b as __pageData,g as default};
